  const det = given ? null : detect(s.domain);
  const pid = given || (det ? det.id : '');
  if (!pid) return;
  const R = s.ranges; const url = 'https://analyticsdata.googleapis.com/v1beta/properties/' + pid + ':runReport';
  const two = [{ startDate: R.current.start, endDate: R.current.end, name: 'current' }, { startDate: R.previous.start, endDate: R.previous.end, name: 'previous' }];
  const req = (kind, body) => out.push({ json: { site_idx: idx, site_id: s.site_id, kind, url, body, ga4_property_id: pid, ga4_detected: !given, ga4_property_name: det ? det.name : '' } });
  req('channels', { dateRanges: two, dimensions: [{ name: 'sessionDefaultChannelGroup' }], metrics: METRICS, limit: 50 });
  req('landing', { dateRanges: two, dimensions: [{ name: 'landingPage' }], metrics: METRICS, dimensionFilter: ORGANIC, orderBys: [{ metric: { metricName: 'sessions' }, desc: true }], limit: 40 });
  // B7-6 (W3-D): sessions from AI assistants (the same source list the AI traffic report uses, Traffic_Requests.js), both periods, no other dimension
  req('ai_ref', { dateRanges: two, metrics: [{ name: 'sessions' }], dimensionFilter: AI_REF_FILTER, limit: 10 });
  req('daily', { dateRanges: [{ startDate: R.previous.start, endDate: R.current.end }], dimensions: [{ name: 'date' }], metrics: METRICS, dimensionFilter: ORGANIC, orderBys: [{ dimension: { dimensionName: 'date' } }], limit: 100 });
});
return out.length ? out : [{ json: { skip: true, reason: acctErr ? 'GA4 account list: ' + acctErr : 'no GA4 property id given or detected for any site' } }];

// Consolidates the GA4 reports per site: organic vs all-channel totals for both periods, organic share, landing pages with deltas, daily organic sessions.
const reqs = $('GA4 Requests').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const gErr = (r) => { if (!r) return 'no response'; const e = r.error; if (!e) return null; if (typeof e === 'string') return e.slice(0, 200); const ctx = (e.context && e.context.data) || {}; const inner = (ctx.error && typeof ctx.error === 'object') ? ctx.error : null; return String((inner && inner.message) || (ctx.error_description ? String(ctx.error || 'error') + ': ' + ctx.error_description : '') || e.message || e.description || e.status || JSON.stringify(e)).slice(0, 200); };   // Google errors: the useful text sits in context.data (invalid_grant: account not found) or in error.message (PERMISSION_DENIED)
const errOf = gErr;
const num = (v) => Number(v) || 0;
const acc = new Map();
reqs.forEach((q, i) => {
  if (q.skip) return;
  if (!acc.has(q.site_idx)) acc.set(q.site_idx, { site_idx: q.site_idx, site_id: q.site_id, ga4_property_id: q.ga4_property_id, ga4_detected: !!q.ga4_detected, ga4_property_name: q.ga4_property_name || '', errors: [], channels: [], landing: [], daily: [], ai_ref: [] });
  const a = acc.get(q.site_idx); const r = res[i]; const e = errOf(r); if (e) { a.errors.push(q.kind + ': ' + e); return; }
  const dims = (r.dimensionHeaders || []).map(h => h.name); const mets = (r.metricHeaders || []).map(h => h.name);
  a[q.kind] = (r.rows || []).map(row => { const o = {}; dims.forEach((d, j) => o[d] = ((row.dimensionValues || [])[j] || {}).value); mets.forEach((m, j) => o[m] = num(((row.metricValues || [])[j] || {}).value)); return o; });
});
const M = (rows) => rows.reduce((t, r) => ({ sessions: t.sessions + (r.sessions || 0), engaged: t.engaged + (r.engagedSessions || 0), key_events: t.key_events + (r.keyEvents || 0), users: t.users + (r.totalUsers || 0) }), { sessions: 0, engaged: 0, key_events: 0, users: 0 });
const out = [];
for (const a of acc.values()) {
  const cur = a.channels.filter(r => r.dateRange === 'current'), prev = a.channels.filter(r => r.dateRange === 'previous');
  const org = (rows) => M(rows.filter(r => r.sessionDefaultChannelGroup === 'Organic Search'));
  const organic = { cur: org(cur), prev: org(prev) }, total = { cur: M(cur), prev: M(prev) };
  // B7-6 (W3-D): the brand series' GA4 lines. Direct = the 'Direct' default channel group; AI referrals = the ai_ref request (null when it failed)
  const direct = { cur: M(cur.filter(r => r.sessionDefaultChannelGroup === 'Direct')), prev: M(prev.filter(r => r.sessionDefaultChannelGroup === 'Direct')) };
  const aiFailed = a.errors.some(e => /^ai_ref:/.test(e));
  const ai_referrals = aiFailed ? null : { cur: M(a.ai_ref.filter(r => r.dateRange === 'current')), prev: M(a.ai_ref.filter(r => r.dateRange === 'previous')) };
  const channels = cur.map(r => ({ channel: r.sessionDefaultChannelGroup, sessions: r.sessions || 0, key_events: r.keyEvents || 0 })).sort((x, y) => y.sessions - x.sessions);
  const lp = new Map();
  for (const r of a.landing) { const k = r.landingPage || '/'; const m = lp.get(k) || { page: k, sessions: 0, prev_sessions: 0, engaged: 0, key_events: 0, prev_key_events: 0 }; if (r.dateRange === 'previous') { m.prev_sessions += r.sessions || 0; m.prev_key_events += r.keyEvents || 0; } else { m.sessions += r.sessions || 0; m.engaged += r.engagedSessions || 0; m.key_events += r.keyEvents || 0; } lp.set(k, m); }
  const landing = [...lp.values()].map(m => ({ ...m, delta: m.sessions - m.prev_sessions })).sort((x, y) => y.sessions - x.sessions).slice(0, 15);
  const daily = a.daily.map(r => ({ date: String(r.date || '').replace(/^(\d{4})(\d{2})(\d{2})$/, '$1-$2-$3'), sessions: r.sessions || 0, engaged: r.engagedSessions || 0, key_events: r.keyEvents || 0 })).sort((x, y) => x.date.localeCompare(y.date));
  out.push({ json: { site_idx: a.site_idx, site_id: a.site_id, ga4_property_id: a.ga4_property_id, ga4_detected: a.ga4_detected, ga4_property_name: a.ga4_property_name, errors: a.errors, organic, total, direct, ai_referrals,
    organic_share: total.cur.sessions ? Math.round(organic.cur.sessions / total.cur.sessions * 100) : 0, channels, landing, daily } });
}
return out.length ? out : [{ json: { skip: true, reason: 'no GA4 data came back' } }];

// URL Inspection (Search Console): what Google thinks of the site's key pages — indexed or not, which canonical it chose, when it last
// crawled them, mobile usability and rich results. Free, but Google's quota is 2,000 inspections a day and 600 a minute per property.
// G25 (2026-10-13, system review FIX_PLAN): it used to ask about the ladder pages only (max 20), so most of the site was never seen through
// Google's eyes. Now every key page rotates through it — the ladder pages and the pages found live this week, the home page and the menu,
// the pages Search Console brings impressions for, the AI pages — ordered **never inspected first, then the oldest inspection**
// (`seo_page_watch.inspect_at`), within the run's share of the quota (PW.PER_RUN). What the budget does not reach rides along as
// `budget.skipped` and is reported as "not checked", never as fine.
// v4.8: pages found live this week by the publish detection (Detect Published) are inspected in the same run.
// ---- the one site model (G19, 2026-10-12; see SITE_MODEL_SPEC.md; the builders inline this file where a node asks for the SITE_MODEL kit) ----
// Every workflow reads the same facts about a site through SM: the canonical host, the business name / logo / NAP (seo_profiles ->
// the homepage Organization / LocalBusiness schema -> Google Business Profile -> the fields the web app sent), the services and nav
// pages, the page inventory (seo_pages), the business facts, the call to action, the brand names, the competitors and the
// accreditation status. SM.from() builds the model, SM.toRow() writes it back to the seo_sites columns.
const SM = (() => {
  const S = (v) => String(v == null ? '' : v).trim();
  const normHost = (v) => S(v).toLowerCase().replace(/^https?:\/\//, '').replace(/[\/?#].*$/, '').replace(/:\d+$/, '');
  const bare = (v) => normHost(v).replace(/^www\./, '');
  const hostOf = (u) => normHost((S(u).match(/^https?:\/\/([^\/?#]+)/i) || [])[1] || '');   // the n8n Code sandbox has no URL constructor
  const siteIdFor = (d) => 'site_' + bare(d).replace(/[^a-z0-9]+/g, '-');
  const listOf = (v) => (Array.isArray(v) ? v : S(v).split(/[\n,;|]+/)).map(x => S(x)).filter(Boolean);
  const uniq = (a) => [...new Set(a)];
  const jparse = (v, dflt) => { if (v && typeof v === 'object') return v; try { const o = JSON.parse(S(v) || 'null'); return o == null ? dflt : o; } catch (e) { return dflt; } };
  const STOP = new Set(['a', 'an', 'and', 'at', 'by', 'for', 'from', 'in', 'into', 'of', 'on', 'or', 'the', 'to', 'vs', 'with', 'your', 'our', 'my']);
  const tokensOf = (s) => S(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(/\s+/).filter(Boolean);
  // one-letter parts ("e" of "e invoicing") and stop words never decide a page match: with them "e invoicing uae penalties" would
  // score 3 of 4 against /uae-e-invoicing-fta-rules/ and claim the FTA page (the S26 false-match pair).
  const termsOf = (s) => uniq(tokensOf(s).filter(t => t.length > 1 && !STOP.has(t)));
  const pathOf = (u) => { const p = S(u).replace(/^https?:\/\/[^\/]*/i, ''); return p || '/'; };
  const strip = (s) => S(s).replace(/<[^>]*>/g, ' ').replace(/&[a-z]+;|&#\d+;/gi, ' ').replace(/\s+/g, ' ').trim();

  // ---- the homepage HTML: canonical host, Organization / LocalBusiness schema, nav pages ----
  const ldNodes = (html) => {
    const out = []; const re = /<script\b[^>]*type\s*=\s*["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi; let m;
    const push = (o) => { if (!o || typeof o !== 'object') return; if (Array.isArray(o)) { o.forEach(push); return; } out.push(o); if (Array.isArray(o['@graph'])) o['@graph'].forEach(push); };
    while ((m = re.exec(S(html)))) push(jparse(m[1], null));
    return out;
  };
  const ORG_TYPE = /(organization|corporation|localbusiness|professionalservice|store|ngo|educationalorganization|governmentorganization|onlinebusiness|softwarecompany|company|consultant|accountingservice)/i;
  const typesOf = (o) => [].concat((o && o['@type']) || []).map(t => S(t).toLowerCase());
  const orgFromHtml = (html) => {
    const nodes = ldNodes(html).filter(o => typesOf(o).some(t => ORG_TYPE.test(t)));
    const node = nodes.find(o => typesOf(o).some(t => /localbusiness|professionalservice|store/.test(t))) || nodes[0];
    if (!node) return null;
    const logo = typeof node.logo === 'string' ? node.logo : ((node.logo || {}).url || '');
    return { name: S(node.name), type: typesOf(node).join('/'), telephone: S(node.telephone), email: S(node.email), logo: S(logo),
      sameAs: listOf(node.sameAs), address: (node.address && typeof node.address === 'object') ? node.address : null };
  };
  const navFromHtml = (html, host) => {
    const h = S(html); const zones = [];
    for (const re of [/<nav\b[\s\S]*?<\/nav>/gi, /<header\b[\s\S]*?<\/header>/gi]) { const f = h.match(re); if (f) zones.push(...f); }
    const out = []; const seen = new Set();
    for (const zone of zones) {
      for (const a of (zone.match(/<a\b[^>]*>[\s\S]*?<\/a>/gi) || [])) {
        const href = S((a.match(/\bhref\s*=\s*["']([^"']+)["']/i) || [])[1]);
        if (!href || /^(#|javascript:|mailto:|tel:)/i.test(href)) continue;
        const abs = /^https?:\/\//i.test(href) ? href : (href.charAt(0) === '/' ? 'https://' + host + href : '');
        if (!abs || bare(hostOf(abs)) !== bare(host)) continue;
        const p = pathOf(abs); if (p === '/' || seen.has(p)) continue;
        seen.add(p); out.push({ url: abs, title: strip(a).slice(0, 80), path: p });
        if (out.length >= 12) return out;
      }
    }
    return out;
  };

  // ---- precedence: seo_profiles -> homepage schema -> Google Business Profile -> what the app sent ----
  const pick = (sources, read) => { for (const s of sources) { const v = S(read(s.value) || ''); if (v) return { value: v, source: s.name }; } return { value: '', source: '' }; };

  const from = (siteRow, extras) => {
    const row = (siteRow && typeof siteRow === 'object') ? siteRow : {};
    const x = (extras && typeof extras === 'object') ? extras : {};
    const req = x.request || {};
    const prof = x.profile || {};
    const gbp = x.gbp || {};
    const html = S(x.html || (x.home || {}).html);
    const domain = bare(row.domain || x.domain || req.domain || (x.home || {}).url || '');
    const site_id = S(row.site_id) || S(x.site_id) || (domain ? siteIdFor(domain) : '');
    const org = x.homepage_org || (html ? orgFromHtml(html) : null) || null;

    // canonical host: this run's probe, else the homepage's own canonical tag, else where the homepage request landed, else the stored
    // value, else the bare domain. A canonical tag on another domain is ignored.
    const canonTag = (S(html).match(/<link\b[^>]*>/gi) || []).find(t => /\brel\s*=\s*["']?canonical\b/i.test(t)) || '';
    const canonHost = hostOf((canonTag.match(/\bhref\s*=\s*["']([^"']+)["']/i) || [])[1] || '');
    const landed = hostOf(x.final_url || (x.home || {}).url || '');
    const fromProbe = normHost(x.canonical_host || (x.probe || {}).canonical_host || '');
    // the site's own live URLs (ladder pages, published pages, sitemap) are evidence too: the host most of them use
